package com.example.takura.media.controller;
import com.example.takura.identity.controller.StaffRequestPrincipal;import com.example.takura.identity.domain.StaffPrincipal;import com.example.takura.media.application.MediaLibraryService;import java.util.UUID;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/media") public class MediaLibraryController {private final MediaLibraryService media;MediaLibraryController(MediaLibraryService media){this.media=media;}@GetMapping Object list(@StaffRequestPrincipal StaffPrincipal actor){return media.list(actor);}@PostMapping Object create(@StaffRequestPrincipal StaffPrincipal actor,@RequestBody MediaLibraryService.Create body){return media.register(actor,body);}@PostMapping("/{id}/clearance") ResponseEntity<?> clear(@StaffRequestPrincipal StaffPrincipal actor,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String etag){if(etag==null)throw new com.example.takura.media.application.UploadService.UploadException(org.springframework.http.HttpStatus.PRECONDITION_REQUIRED,"PRECONDITION_REQUIRED","If-Match is required.");long revision=Long.parseLong(etag.replace("\"", ""));var result=media.clear(actor,id,revision);return ResponseEntity.ok().eTag(Long.toString(result.revision())).body(result);}}
